inputs = ['ahufzf', 'ejak', 'ud', 'gza', 'zfdbgb']
outputs = ['ajaza', 'ejak', 'ugd', 'gza', 'zadbgb']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{out}'")
    if inp != out:
        # Let's manually check what's different
        min_len = min(len(inp), len(out))
        prefix_len = 0
        suffix_len = 0

        # Find common prefix
        for j in range(min_len):
            if inp[j] == out[j]:
                prefix_len += 1
            else:
                break

        # Find common suffix  
        for j in range(1, min_len + 1):
            if inp[-j] == out[-j]:
                suffix_len += 1
            else:
                break

        print(f"  Common prefix length: {prefix_len}")
        print(f"  Common suffix length: {suffix_len}")

        # What's left in input and output
        if prefix_len + suffix_len <= len(inp):
            inp_middle = inp[prefix_len:len(inp)-suffix_len if suffix_len > 0 else len(inp)]
            out_middle = out[prefix_len:len(out)-suffix_len if suffix_len > 0 else len(out)]
            print(f"  Middle part in input: '{inp_middle}'")
            print(f"  Middle part in output: '{out_middle}'")

